type SealProps = {
  className?: string;
  /** Colour of the outer ring + arced lettering. */
  ringColor?: string;
  /** Colour of the central scales/robe emblem. */
  emblemColor?: string;
  /** Rendered as the accessible name. */
  title?: string;
};

/**
 * <StratumSeal> — the primary logo, used sitewide: header, footer, hero,
 * favicon source, and OG image source.
 */
export function StratumSeal({
  className,
  ringColor = 'currentColor',
  emblemColor = 'currentColor',
  title,
}: SealProps) {
  return (
    <svg
      viewBox="0 0 1280 1280"
      className={className}
      role="img"
      aria-label={title ?? `${FIRM_TRADING_NAME} seal`}
    >
      <g transform={TRANSFORM} fill={ringColor} stroke="none">
        <path d={RING_PATH} />
      </g>
      <g transform={TRANSFORM} fill={emblemColor} stroke="none">
        <path d={EMBLEM_PATH} />
      </g>
    </svg>
  );
}
